-- Produces tests/isolated/schema.sql: the STRUCTURE of the public schema as one
-- text value, in the sections apply-schema.sh applies in order. Reads the
-- catalog only — no table rows.
with
tbls as (
  select c.oid, c.relname, c.relrowsecurity, c.relforcerowsecurity
  from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='r'),
seqs as (select coalesce(string_agg(format('CREATE SEQUENCE IF NOT EXISTS public.%I;', sequencename), E'\n'), '') s from pg_sequences where schemaname='public'),
cols as (
  select t.oid, string_agg(
    format('  %I %s%s%s', a.attname, format_type(a.atttypid,a.atttypmod),
      case when a.attgenerated='s' then ' GENERATED ALWAYS AS ('||pg_get_expr(d.adbin,d.adrelid)||') STORED'
           when a.attidentity='a' then ' GENERATED ALWAYS AS IDENTITY'
           when a.attidentity='d' then ' GENERATED BY DEFAULT AS IDENTITY'
           when d.adbin is not null then ' DEFAULT '||pg_get_expr(d.adbin,d.adrelid) else '' end,
      case when a.attnotnull then ' NOT NULL' else '' end),
    E',\n' order by a.attnum) c
  from tbls t join pg_attribute a on a.attrelid=t.oid and a.attnum>0 and not a.attisdropped
  left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
  group by t.oid),
create_tables as (select string_agg(format(E'CREATE TABLE public.%I (\n%s\n);', t.relname, c.c), E'\n\n' order by t.relname) s from tbls t join cols c using(oid)),
cons as (
  select string_agg(format('ALTER TABLE public.%I ADD CONSTRAINT %I %s;', cl.relname, co.conname, pg_get_constraintdef(co.oid)), E'\n'
     order by case co.contype when 'p' then 1 when 'u' then 2 when 'c' then 3 when 'x' then 4 else 5 end, cl.relname, co.conname) s
  from pg_constraint co join pg_class cl on cl.oid=co.conrelid
  where cl.relnamespace='public'::regnamespace and cl.relkind='r' and co.contype in ('p','u','c','f','x')),
idx as (select coalesce(string_agg(i.indexdef||';', E'\n' order by i.indexname), '') s from pg_indexes i
  where i.schemaname='public' and not exists (select 1 from pg_constraint co join pg_class ic on ic.oid=co.conindid where ic.relname=i.indexname and ic.relnamespace='public'::regnamespace)),
funcs as (select coalesce(string_agg(pg_get_functiondef(p.oid)||';', E'\n\n' order by p.proname, p.oid), '') s from pg_proc p where p.pronamespace='public'::regnamespace and p.prokind in ('f','p')),
trgs as (select coalesce(string_agg(pg_get_triggerdef(t.oid)||';', E'\n' order by c.relname, t.tgname), '') s from pg_trigger t join pg_class c on c.oid=t.tgrelid where c.relnamespace='public'::regnamespace and c.relkind='r' and not t.tgisinternal),
rls as (select coalesce(string_agg(format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;', relname) || case when relforcerowsecurity then format(E'\nALTER TABLE public.%I FORCE ROW LEVEL SECURITY;', relname) else '' end, E'\n' order by relname), '') s from tbls where relrowsecurity),
pols as (select coalesce(string_agg(format('CREATE POLICY %I ON public.%I AS %s FOR %s TO %s%s%s;', policyname, tablename, permissive, cmd, array_to_string(roles, ', '), case when qual is not null then ' USING ('||qual||')' else '' end, case when with_check is not null then ' WITH CHECK ('||with_check||')' else '' end), E'\n' order by tablename, policyname), '') s from pg_policies where schemaname='public'),
grants as (select coalesce(string_agg(format('GRANT %s ON public.%I TO %I;', privs, table_name, grantee), E'\n' order by table_name, grantee), '') s from (select table_name, grantee, string_agg(privilege_type, ', ' order by privilege_type) privs from information_schema.role_table_grants where table_schema='public' and grantee in ('anon','authenticated','service_role') group by 1,2) g),
fgrants as (select coalesce(string_agg(format('GRANT EXECUTE ON FUNCTION public.%I(%s) TO %I;', routine_name, pg_get_function_identity_arguments((specific_schema||'.'||routine_name)::regproc), grantee), E'\n'), '') s from information_schema.routine_privileges rp where specific_schema='public' and grantee in ('anon','authenticated','service_role') and (select count(*) from pg_proc p where p.pronamespace='public'::regnamespace and p.proname=rp.routine_name)=1)
select
  E'-- @@section sequences\n' || (select s from seqs) ||
  E'\n-- @@section functions\n' || (select s from funcs) ||
  E'\n-- @@section tables\n' || (select s from create_tables) ||
  E'\n-- @@section constraints\n' || (select s from cons) ||
  E'\n-- @@section indexes\n' || (select s from idx) ||
  E'\n-- @@section triggers\n' || (select s from trgs) ||
  E'\n-- @@section rls\n' || (select s from rls) ||
  E'\n-- @@section policies\n' || (select s from pols) ||
  E'\n-- @@section grants\n' || (select s from grants) || E'\n' || (select s from fgrants) || E'\n' as schema_sql;
